begin;
do $$
declare owner_id uuid:=gen_random_uuid();pupil uuid:=gen_random_uuid();parent_id uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();school uuid:=gen_random_uuid();student uuid:=gen_random_uuid();fresh uuid:=gen_random_uuid();oldclass uuid:=gen_random_uuid();newclass uuid:=gen_random_uuid();member uuid:=gen_random_uuid();subject uuid:=gen_random_uuid();book uuid:=gen_random_uuid();route uuid:=gen_random_uuid();oldroute uuid;newroute uuid;loan uuid;assignment uuid:=gen_random_uuid();denied boolean;n int;
begin
insert into auth.users(id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)select v,'authenticated','authenticated','session-test-'||v||'@example.invalid','{}','{"first_name":"Session","last_name":"Fixture"}',now(),now() from unnest(array[owner_id,pupil,parent_id,outsider])v;
insert into public.schoolpro_schools(id,owner_id,name,code)values(school,owner_id,'Operational session fixture','SESS-'||school);
insert into public.schoolpro_subscriptions(school_id,tier,billing_cycle,status,renews_at)values(school,'enterprise','annual','active',now()+interval '365 days');
update public.schoolpro_schools set status='active' where id=school;
insert into public.schoolpro_classes(id,school_id,name,arm,level)values(oldclass,school,'Basic 1','A','primary'),(newclass,school,'Basic 2','A','primary');
insert into public.schoolpro_students(id,school_id,admission_number,first_name,last_name,class_id,class_name,user_id)values(student,school,'S-1','Historic','Pupil',newclass,'Basic 2 A',pupil),(fresh,school,'S-2','New','Pupil',oldclass,'Basic 1 A',outsider);
insert into public.schoolpro_enrollment_history(school_id,student_id,session,class_id,class_name,arm,section,status)values(school,student,'2025/2026',oldclass,'Basic 1','A','primary','completed'),(school,student,'2026/2027',newclass,'Basic 2','A','primary','active'),(school,fresh,'2026/2027',oldclass,'Basic 1','A','primary','active');
insert into public.schoolpro_guardian_links(school_id,student_id,guardian_user_id,status,linked_by)values(school,student,parent_id,'active',owner_id);
insert into public.schoolpro_subjects(id,school_id,name,code,class_name)values(subject,school,'Maths','MTH','Basic 1 A');
insert into public.schoolpro_members(id,school_id,user_id,role)values(member,school,parent_id,'teacher');
insert into public.schoolpro_result_term_settings(school_id,session,term,term_start_date,term_end_date)values(school,'2025/2026','First Term','2025-09-01','2025-12-20'),(school,'2026/2027','First Term','2026-09-01','2026-12-20');
insert into public.schoolpro_library_books(id,school_id,title,copies,available_copies)values(book,school,'Session fixture',2,2);
insert into public.schoolpro_transport_routes(id,school_id,name)values(route,school,'Session route');
insert into public.schoolpro_assignments(id,school_id,class_id,subject_id,title,session,created_by)values(assignment,school,oldclass,subject,'Previous-year class work','2025/2026',owner_id);
insert into public.schoolpro_timetable_entries(school_id,class_id,subject_id,weekday,starts_at,ends_at,session)values(school,oldclass,subject,1,'09:00','10:00','2025/2026'),(school,newclass,subject,1,'09:00','10:00','2026/2027');
perform set_config('request.jwt.claim.sub',owner_id::text,true);execute 'set local role authenticated';
oldroute:=public.assign_schoolpro_transport(route,student,'Old stop','2025/2026');
newroute:=public.assign_schoolpro_transport(route,student,'New stop','2026/2027');
if oldroute=newroute or(select pickup_point from public.schoolpro_student_transport where id=oldroute)<>'Old stop' then raise exception 'Transport history overwritten';end if;
perform public.assign_schoolpro_transport(route,student,'Revised stop','2026/2027');
if(select count(*) from public.schoolpro_student_transport where student_id=student)<>2 then raise exception 'Repeated route created duplicates';end if;
loan:=public.borrow_schoolpro_library_book(book,student,null,now()+interval '7 days','2026/2027');
if(select session from public.schoolpro_library_loans where id=loan)<>'2026/2027' then raise exception 'Loan lost selected session';end if;
perform public.return_schoolpro_library_book(loan,0);perform public.return_schoolpro_library_book(loan,0);
if(select available_copies from public.schoolpro_library_books where id=book)<>2 then raise exception 'Library return changed shared stock twice';end if;
denied:=false;begin update public.schoolpro_library_loans set session='2025/2026' where id=loan;exception when others then denied:=position('original academic session' in SQLERRM)>0;end;if not denied then raise exception 'Loan was moved to a different year';end if;
insert into public.schoolpro_attendance(school_id,student_id,class_id,attendance_date,status,session,marked_by)values(school,student,oldclass,'2025-10-01','present','2025/2026',owner_id);
denied:=false;begin insert into public.schoolpro_attendance(school_id,student_id,class_id,attendance_date,status,session,marked_by)values(school,student,oldclass,'2026-10-01','present','2025/2026',owner_id);exception when others then denied:=position('outside' in SQLERRM)>0;end;if not denied then raise exception 'Attendance date/session mismatch accepted';end if;
perform set_config('request.jwt.claim.sub',pupil::text,true);
select count(*) into n from public.schoolpro_assignments where id=assignment;if n<>1 then raise exception 'Promoted pupil cannot see historical class assignment';end if;
select count(*) into n from public.schoolpro_timetable_entries where school_id=school and session='2025/2026';if n<>1 then raise exception 'Historical timetable not available to pupil';end if;
perform set_config('request.jwt.claim.sub',outsider::text,true);
select count(*) into n from public.schoolpro_assignments where id=assignment;if n<>0 then raise exception 'New-session pupil sees previous class work';end if;
denied:=false;begin perform public.assign_schoolpro_transport(route,student,'Intruder','2026/2027');exception when others then denied:=true;end;if not denied then raise exception 'Unrelated pupil assigned another pupil';end if;
execute 'reset role';
end $$;
rollback;